function saveActionForm(f,id){if(!trackerCanEdit()){trackerShowError('Switch to BU contributor preview to edit action plans.');return false}const k=trackerKpi(f.targetKpiId);if(f.targetKpiId&&!k){trackerShowError('Choose an existing KPI record.');return false}if(!f.title?.trim()||!f.owner?.trim()||!f.bu?.trim()){trackerShowError('Plan, responsible owner and business unit are required.');return false}if(!String(f.progress??'').trim()||!Number.isFinite(+f.progress)||+f.progress<0||+f.progress>100){trackerShowError('Progress must be a number from 0 to 100.');return false}if(!['','Planned',...trackerStatuses,'Decision required'].includes(trackerStatus(f.status))){trackerShowError('Choose a supported action status.');return false}if(!trackerValidDate(f.due)||!trackerValidDate(f.updated||trackerToday())){trackerShowError('Choose valid calendar deadline and update dates.');return false}const old=id?db.actions.find(a=>a.id===id):null;if(id&&!old)return false;const before=old?structuredClone(old):null;const a=old||{id:'a'+Date.now(),history:[],planningRemarks:''};const fields=['title','owner','targetCompletion','targetKpiId','kpiLinked','notes','commitment','corrective'];for(const key of fields)a[key]=String(f[key]??old?.[key]??'').trim();a.bu=k?trackerUnit(k.unitId).name:f.bu.trim();a.status=trackerStatus(f.status);a.progress=a.status==='Complete'?100:+f.progress;a.due=f.due;a.updated=f.updated||trackerToday();trackerHistory(a,old?'Action plan updated':'Action plan created',trackerChanges(before,a,{title:'Action Item / Plan',owner:'Owner',bu:'BU',targetKpiId:'KPI record link',kpiLinked:'KPI Linked',targetCompletion:'Target Completion',due:'Calendar deadline',progress:'Progress',status:'Current Status',updated:'Last Updated',notes:'BU Notes',commitment:'Commitment',corrective:'Corrective action'}));if(!old)db.actions.unshift(a);log((old?'Updated action: ':'Added action: ')+a.title);closeModal();render();toast('Action plan saved locally. No shared account or sheet was updated.');return true}
function issueModal(id){const i=db.issues.find(x=>x.id===id);if(!i)return;const reportId=issueReportLinks[id];modal(esc(i.title),`<div class="report-detail-top"><span class="badge blue">Read-only summary</span>${badge(i.status)}${badge(i.escalated?'Decision required':'Open')}</div><dl class="definition-list"><dt>Business unit</dt><dd>${esc(i.bu)}</dd><dt>Reported owner</dt><dd>${esc(i.owner)}</dd><dt>Severity</dt><dd>${esc(i.severity)}</dd><dt>Resolution target</dt><dd>${fmtDate(i.due)} 2026</dd><dt>Escalation status</dt><dd>${i.escalated?'Shown for management attention in this sample':'Shown for owner review in this sample'}</dd></dl><h3>Reported blocker / support needed</h3><p>${esc(i.detail)}</p><div class="detail-note">Illustrative linked-report summary. The issue’s source mapping is not confirmed. GOS does not submit an escalation, resolve the issue or change its source status.</div>`,button('Close','close')+(reportId?button('View linked PACE','pace:'+reportId,'primary','document'):''),'GOS · Issue viewing')}
function projectModal(id){const p=db.projects.find(x=>x.id===id);modal(p.title,`<div style="display:flex;gap:8px">${badge(p.portfolio)}${badge(p.status)}</div><dl class="definition-list"><dt>Accountable owner</dt><dd>${p.owner}</dd><dt>Target date</dt><dd>${fmtDate(p.due)} 2026</dd><dt>Budget</dt><dd>${p.budget}</dd><dt>Source</dt><dd>${p.portfolio==='Pulse'?'Gie’s Google Sheet · planned':'BU project inputs · for validation'}</dd></dl>${progress(p.progress)}<div class="spacer"></div><h3>Milestones</h3>${p.milestones.map((m,i)=>`<label class="check-item"><input type="checkbox" data-milestone="${p.id}:${i}" ${p.checked?p.checked.includes(i)?'checked':'':i<Math.floor(p.progress/34)?'checked':''}>${m}</label>`).join('')}<div class="spacer"></div><h3>Risk / blocker</h3><p>${p.risk}</p><div class="spacer"></div><h3>Next action</h3><p>${p.next}</p><div class="detail-note">Milestone checkboxes update sample completion locally. No source document is modified.</div>`,button('Close','close')+button('Open action plans','goto:actions','primary','arrow'),'GED · Project detail')}
function paceModal(id){const p=hrisPaceReports.find(r=>r.id===id);if(!p){toast('This sample report is not available.');return}modal('PACE report',`<div class="report-detail-top"><span class="badge blue">Read-only · HRIS-origin sample</span>${reportStatus(p.status)}</div><dl class="definition-list"><dt>Report ID</dt><dd>${p.id}</dd><dt>Contributor</dt><dd>${p.person}</dd><dt>Business unit</dt><dd>${p.bu}</dd><dt>Operating date</dt><dd>${fmtDate(p.date)} 2026</dd><dt>Created at source</dt><dd>${p.submitted}</dd><dt>Last source update</dt><dd>${p.updated}</dd></dl><div class="pace-detail-fields">${[['Priority',p.priority],['Accountability',p.accountability],['Challenges',p.challenges],['Expectation',p.expectation]].map(([label,value])=>`<section><h3>${label}</h3><p>${esc(value)}</p></section>`).join('')}</div><div class="spacer"></div><h3>Source history · illustrative</h3><div class="report-history">${p.history.slice().reverse().map(([time,title,detail])=>`<div class="activity"><strong>${title}</strong><small>${time}</small><p>${detail}</p></div>`).join('')}</div><div class="detail-note">PACE is created and updated in HRIS. This GOS view cannot change the report. The HRIS PACE integration is planned; these records are examples, not fetched data.</div>`,button('Close','close'),'GOS · Read-only PACE viewing')}
