function trackerTotals(){const d=trackerData(),salesUnits=d.units.filter(u=>u.group!=='Pulse'),sales=salesUnits.reduce((s,u)=>s+u.sales,0),reserves=salesUnits.reduce((s,u)=>s+u.reserves,0),scoreValues=d.units.filter(u=>u.group==='Pulse'&&u.score!==null),targetValues=d.units.filter(u=>u.group==='Pulse'&&u.scoreTarget!==null);return {sales,reserves,combined:sales+reserves,salesGap:Math.max(0,d.settings.salesTarget-sales),reservesGap:Math.max(0,d.settings.reservesTarget-reserves),eligible:sales>=d.settings.salesTarget&&reserves>=d.settings.reservesTarget,score:scoreValues.length?scoreValues.reduce((s,u)=>s+u.score,0)/scoreValues.length:null,scoreTarget:targetValues.length?targetValues.reduce((s,u)=>s+u.scoreTarget,0)/targetValues.length:null}}
function trackerHistory(record,kind,changes,note=''){record.history=record.history||[];record.history.unshift({at:new Date().toLocaleString('en-GB',{timeZone:'Asia/Manila'})+' PHT',actor:trackerActor(),kind,changes:changes||[],note});record.history=record.history.slice(0,50)}
function trackerChanges(before,after,labels){return Object.entries(labels).filter(([k])=>String(before?.[k]??'')!==String(after[k]??'')).map(([k,label])=>({field:label,from:String(before?.[k]??''),to:String(after[k]??'')}))}
function trackerHistoryHTML(record){return `<div class="tracker-history">${record.history?.length?record.history.map(h=>`<article><strong>${esc(h.kind)}</strong><small>${esc(h.actor)} · ${esc(h.at)}</small>${h.changes?.length?`<ul>${h.changes.map(c=>`<li>${esc(c.field)}: ${esc(c.from||'(unset)')} → ${esc(c.to||'(unset)')}</li>`).join('')}</ul>`:''}${h.note?`<p>${esc(h.note)}</p>`:''}</article>`).join(''):'<div class="subtle-note">Seeded sample record. No local changes have been made yet.</div>'}</div>`}
function trackerRoleBar(){return `<div class="tracker-rolebar"><div class="local-demo-label">${icon('shield')}<span><strong>Local demo workspace</strong><small>Sample values · role preview only · no real accounts or shared access control</small></span></div><div class="role-selector"><span>Preview as</span><select aria-label="KPI demo role" data-tracker-role><option value="bu" ${state.trackerRole==='bu'?'selected':''}>BU contributor</option><option value="planning" ${state.trackerRole==='planning'?'selected':''}>Corporate Planning</option><option value="viewer" ${state.trackerRole==='viewer'?'selected':''}>Executive viewer</option></select></div></div>`}
function trackerFilterBar(){const us=trackerData().units.filter(u=>state.trackerGroup==='All'||u.group===state.trackerGroup);return `<div class="tracker-filters"><label>Portfolio<select data-tracker-filter="trackerGroup" aria-label="KPI portfolio">${options(['All','Nexus','Corelink','Pulse'],state.trackerGroup)}</select></label><label>Business unit<select data-tracker-filter="trackerUnit" aria-label="KPI business unit"><option value="All">All sample BUs</option>${us.map(u=>`<option value="${u.id}" ${state.trackerUnit===u.id?'selected':''}>${u.name}</option>`).join('')}</select></label>${state.trackerTab!=='rollup'?`<label>Status<select data-tracker-filter="trackerStatus" aria-label="KPI status">${options(['All',...trackerStatuses,'Planned','N/A','Not set'],state.trackerStatus)}</select></label>`:''}<label class="tracker-search">Search<input data-tracker-search aria-label="Search KPIs and plans" placeholder="KPI, plan, owner or note…" value="${esc(state.trackerSearch)}"></label>${button('Reset','tracker-reset-filters','small','refresh')}</div>`}
function trackerMatches(unitId,status='',text=''){const u=trackerUnit(unitId);return u&&(state.trackerGroup==='All'||u.group===state.trackerGroup)&&(state.trackerUnit==='All'||u.id===state.trackerUnit)&&(state.trackerStatus==='All'||(state.trackerStatus==='Not set'?!status:trackerStatus(status)===state.trackerStatus))&&(!state.trackerSearch||text.toLowerCase().includes(state.trackerSearch.toLowerCase()))}
function targets(){return `${trackerRoleBar()}<div class="tracker-tabs">${[['rollup','Targets & rollup','chart'],['register','KPI register','target'],['planning','Planning review','flag']].map(([id,label,ic])=>`<button class="${state.trackerTab===id?'active':''}" data-action="tracker-tab:${id}">${icon(ic)}${label}${id==='planning'?`<span>${db.actions.filter(a=>trackerFlagged(a.status)).length}</span>`:''}</button>`).join('')}<button data-nav="actions">${icon('plan')}Action plans ${icon('arrow')}</button></div>${trackerFilterBar()}${state.trackerTab==='rollup'?trackerRollup():state.trackerTab==='register'?trackerRegister():trackerPlanning()}<p class="tracker-source-note">Template-based sample values only · Browser-local inputs, no multiuser sync or original-sheet writeback. All source data remains unchanged.</p>`}
function trackerRollup(){const d=trackerData(),t=trackerTotals(),moneyUnits=d.units.filter(u=>u.group!=='Pulse'&&trackerMatches(u.id,'',u.name+' '+u.company+' '+u.notes)),pulseUnits=d.units.filter(u=>u.group==='Pulse'&&trackerMatches(u.id,'',u.name+' '+u.notes));return `<div class="tracker-period"><span><strong>90-day sample cycle</strong> ${esc(d.settings.start)} → ${esc(d.settings.end)}</span><span><strong>Company deadline</strong> ${esc(d.settings.deadline)} · ${trackerDays(d.settings.deadline)} days left</span>${trackerCanReview()?button('Configure sample goals','tracker-goals','small','edit'):''}</div><div class="tracker-goals"><section class="panel"><div class="panel-head"><h2>Gross Sales</h2><span class="badge">Company total</span></div><div class="panel-body"><div class="tracker-goal-value">${trackerCompact(t.sales)}</div><div class="tracker-goal-target">Target ${trackerCompact(d.settings.salesTarget)}</div>${progress(Math.round(trackerPct(t.sales,d.settings.salesTarget)))}<dl><dt>Still needed</dt><dd>${trackerCompact(t.salesGap)}</dd><dt>Days left</dt><dd>${trackerDays(d.settings.deadline)}</dd></dl></div></section><section class="panel"><div class="panel-head"><h2>Reserves</h2><span class="badge">Separate goal</span></div><div class="panel-body"><div class="tracker-goal-value">${trackerCompact(t.reserves)}</div><div class="tracker-goal-target">Target ${trackerCompact(d.settings.reservesTarget)}</div>${progress(Math.round(trackerPct(t.reserves,d.settings.reservesTarget)))}<dl><dt>Still needed</dt><dd>${trackerCompact(t.reservesGap)}</dd><dt>Days left</dt><dd>${trackerDays(d.settings.deadline)}</dd></dl></div></section><section class="panel"><div class="panel-head"><h2>Combined view</h2></div><div class="panel-body"><div class="tracker-goal-value">${trackerCompact(t.combined)}</div><div class="tracker-goal-target">Combined target ${trackerCompact(d.settings.salesTarget+d.settings.reservesTarget)}</div><div class="tracker-eligibility ${t.eligible?'met':''}">${icon(t.eligible?'check':'info')}<div><strong>${t.eligible?'Both goals reached':'Both goals required'}</strong><span>Sample incentive preview: Gross Sales AND Reserves must each reach target. A combined total alone does not qualify.</span></div></div></div></section></div><p class="tracker-scope-note">Company totals above include all financial sample BUs, regardless of table filters. Pulse support scores are excluded from monetary totals.</p><section class="panel"><div class="panel-head"><div><h2>Sales contribution by business unit</h2><p>Current Sales and 90-Day Sales Target are inputs; totals, gaps and ratios are calculated</p></div></div><div class="table-wrap"><table><thead><tr><th>Business unit / company</th><th>Current Sales</th><th>90-Day Target</th><th>Still Needed</th><th>% Reached</th><th>Company contribution</th><th></th></tr></thead><tbody>${moneyUnits.map(u=>`<tr><td><strong>${u.name}</strong><div class="report-subtext">${u.group} · ${u.company}</div></td><td>${trackerPHP(u.sales)}</td><td>${trackerPHP(u.target)}</td><td>${trackerPHP(u.target-u.sales)}</td><td>${trackerPct(u.sales,u.target).toFixed(1)}%</td><td>${trackerPct(u.sales,d.settings.salesTarget).toFixed(1)}%</td><td>${button(trackerCanEdit()?'Update':'View','tracker-unit:'+u.id,'small',trackerCanEdit()?'edit':'chevron')}</td></tr>`).join('')}</tbody></table></div>${!moneyUnits.length?'<div class="empty">No financial rows match these filters.</div>':''}<div class="table-footer">BU gaps retain negative values when above target. Company gaps are floored at zero. A zero BU target returns 0% in this template.</div></section><div class="spacer"></div><div class="two-col"><section class="panel"><div class="panel-head"><h2>Reserves contributions</h2></div><div class="panel-body"><div class="review-list">${d.units.filter(u=>u.group!=='Pulse'&&trackerMatches(u.id,'',u.name+' '+u.company)).map(u=>`<div class="review-item"><div style="flex:1"><strong>${u.name}</strong><small>${u.group}</small></div><strong>${trackerPHP(u.reserves)}</strong>${button(trackerCanEdit()?'Update':'View','tracker-unit:'+u.id,'small')}</div>`).join('')||'<div class="empty">No contributions in this scope.</div>'}</div></div></section><section class="panel"><div class="panel-head"><div><h2>Pulse support score</h2><p>Current / target score · 1–10 scale</p></div><span class="badge">Average, not sum</span></div><div class="panel-body"><div class="tracker-score-summary"><strong>${t.score===null?'Not assessed':t.score.toFixed(1)}</strong><span>Average current score</span><strong>${t.scoreTarget===null?'Not set':t.scoreTarget.toFixed(1)}</strong><span>Average target score</span></div><div class="review-list">${pulseUnits.map(u=>`<div class="review-item"><div style="flex:1"><strong>${u.name}</strong><small>${u.score===null?'Not assessed':u.score+' / '+(u.scoreTarget??'—')+' · gap '+(u.scoreTarget===null?'—':(u.scoreTarget-u.score).toFixed(1))+' · '+(u.scoreTarget===null?'target not set':trackerPct(u.score,u.scoreTarget).toFixed(1)+'%')}</small></div>${button(trackerCanEdit()?'Update':'View','tracker-unit:'+u.id,'small')}</div>`).join('')||'<div class="subtle-note">Choose Pulse or All portfolios to see support-score entries.</div>'}</div><div class="detail-note">Blank scores are not assessed, not zero performance. Averages ignore unset values. Pulse scores never enter sales/reserves totals.</div></div></section></div>`}
function trackerRegister(){const rows=trackerData().kpis.filter(k=>trackerMatches(k.unitId,k.status,[k.name,k.owner,k.notes].join(' ')));return `<section class="panel tracker-register"><div class="panel-head"><div><h2>30 / 60 / 90-day KPI register <span class="record-count">${rows.length}</span></h2><p>Manual self-check status; text, ranges, N/A and unset values stay distinct from zero</p></div>${trackerCanEdit()?button('Add KPI','tracker-add-kpi','primary','plus'):''}</div><div class="table-wrap"><table><thead><tr><th>Business unit / KPI</th><th>Baseline</th><th>30-Day</th><th>60-Day</th><th>90-Day</th><th>Actual</th><th>Status</th><th class="sticky-details"><span class="sr-only">Details</span></th></tr></thead><tbody>${rows.map(k=>`<tr><td class="tracker-description"><strong>${esc(k.name)}</strong><div class="report-subtext">${trackerUnit(k.unitId).name} · ${esc(k.owner)}</div></td><td>${trackerText(k.baseline)}</td><td>${trackerText(k.day30)}</td><td>${trackerText(k.day60)}</td><td>${trackerText(k.day90)}</td><td>${trackerText(k.actual)}</td><td>${trackerBadge(k.status)}</td><td class="sticky-details">${button('Details','tracker-kpi:'+k.id,'small','chevron')}</td></tr>`).join('')}</tbody></table></div>${!rows.length?'<div class="empty">No KPIs match these filters.</div>':''}<div class="table-footer">The source field is “Actual (Live)”; this prototype uses manually entered sample values only. KPI status is never calculated from attainment.</div></section>`}
function trackerPlanning(){const rows=db.actions.filter(a=>trackerFlagged(a.status)).filter(a=>{const k=trackerKpi(a.targetKpiId),u=k?trackerUnit(k.unitId):trackerData().units.find(u=>u.name===a.bu),text=[a.title,a.owner,a.notes,a.bu].join(' ');return u?trackerMatches(u.id,a.status,text):(state.trackerGroup==='All'&&state.trackerUnit==='All'&&(state.trackerStatus==='All'||trackerStatus(a.status)===state.trackerStatus)&&(!state.trackerSearch||text.toLowerCase().includes(state.trackerSearch.toLowerCase())))});return `<div class="notice">${icon('flag')}At Risk or Delayed action status is the source-defined cue for Corporate Planning to review. The red border marks that cue. Other statuses do not enter this weekly exception queue.</div><section class="panel"><div class="panel-head"><div><h2>Corporate Planning exception review</h2><p>BU self-check → highlighted status → Planning remarks</p></div><span class="badge">${rows.length} flagged</span></div><div class="panel-body"><div class="review-list">${rows.map(a=>`<article class="tracker-exception"><div class="tracker-exception-head"><div><strong>${esc(a.title)}</strong><small>${esc(a.bu)} · ${esc(a.owner)} · ${esc(a.updated||'Not set')}</small></div><span class="tracker-status-cell flagged">${trackerBadge(a.status)}</span></div><p><b>BU Notes:</b> ${esc(a.notes||a.corrective||'No note entered')}</p><p><b>CP Remarks:</b> ${esc(a.planningRemarks||'No remarks yet')}</p><div>${button('Open action plan','action:'+a.id,'small','chevron')}${trackerCanReview()?button('Add remarks','tracker-remarks:'+a.id,'small primary','edit'):''}</div></article>`).join('')||'<div class="empty">No At Risk or Delayed action plans match these filters.</div>'}</div><div class="detail-note">Separate CP Remarks and local change history are prototype workflow enhancements; the source action table provides Notes. Remarks are not approvals, notifications or original-sheet comments.</div></div></section>`}
const trackerTextArea=(name,label,value='',required=false)=>`<div class="field"><label for="tt-${name}">${label}</label><textarea id="tt-${name}" name="${name}" maxlength="1600" ${required?'required':''}>${esc(value)}</textarea></div>`;
const trackerInput=(name,label,value='',type='text',required=false,extra='')=>`<div class="field"><label for="tt-${name}">${label}</label><input id="tt-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></div>`;
const trackerSelect=(name,label,items,value)=>`<div class="field"><label for="tt-${name}">${label}</label><select name="${name}" id="tt-${name}">${items.map(([v,l])=>`<option value="${esc(v)}" ${value===v?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;
const trackerErrors=()=>'<div id="tracker-form-error" class="tracker-error" role="alert" hidden></div>';
function trackerShowError(message){const e=$('#tracker-form-error');if(e){e.hidden=false;e.textContent=message;e.focus?.()}else toast(message)}
function trackerKpiModal(id,edit=false){const k=trackerKpi(id);if(!k&&!edit)return;if(edit&&!trackerCanEdit()){toast('Switch to the BU contributor preview to enter KPI data.');return}const v=k||{id:'',unitId:state.trackerUnit!=='All'?state.trackerUnit:trackerData().units[0].id,name:'',baseline:'',day30:'',day60:'',day90:'',actual:'',status:'',owner:'Demo BU team',updated:trackerToday(),notes:''};if(edit){modal(k?'Edit KPI & targets':'Add KPI & targets',`<form id="tracker-form" data-form="tracker-kpi" data-id="${id||''}">${trackerErrors()}<div class="form-section-label"><span>01</span> KPI & accountability</div><div class="field-grid">${trackerSelect('unitId','Business unit',trackerData().units.map(u=>[u.id,u.name+' · '+u.group]),v.unitId)}${trackerInput('name','KPI',v.name,'text',true,'maxlength="180"')}</div>${trackerInput('owner','Responsible person / team (sample)',v.owner,'text',true,'maxlength="180"')}<div class="form-section-label"><span>02</span> Baseline & milestone targets</div><div class="field-grid">${trackerInput('baseline','Baseline',v.baseline,'text',false,'maxlength="200"')}${trackerInput('actual','Actual (sample input)',v.actual,'text',false,'maxlength="200"')}</div><div class="tracker-three-fields">${trackerInput('day30','30-Day Target',v.day30,'text',false,'maxlength="200"')}${trackerInput('day60','60-Day Target',v.day60,'text',false,'maxlength="200"')}${trackerInput('day90','90-Day Target',v.day90,'text',false,'maxlength="200"')}</div><div class="form-section-label"><span>03</span> Self-check & notes</div><div class="field-grid">${trackerSelect('status','Manual self-check status',[['','Not set'],...trackerStatuses.map(s=>[s,s]),['N/A','N/A']],v.status)}${trackerInput('updated','Last Updated',v.updated,'date',true)}</div>${trackerTextArea('notes','Notes',v.notes)}<p class="formhint">Text, units, ratios and ranges are accepted. Leave unknown values blank, or enter “To establish” / “N/A”; they will not become zero. This is a local demo input, not a source-sheet update.</p></form>`,button('Cancel','close')+'<button class="btn primary" type="submit" form="tracker-form">Save KPI</button>','KPI & Targets · '+trackerActor());return}const u=trackerUnit(k.unitId),plans=db.actions.filter(a=>a.targetKpiId===k.id);modal(esc(k.name),`<div class="report-detail-top"><span class="badge">${u.group} · ${u.name}</span>${trackerBadge(k.status)}</div><dl class="definition-list"><dt>Owner</dt><dd>${esc(k.owner)}</dd><dt>Baseline</dt><dd>${trackerText(k.baseline)}</dd><dt>30-Day Target</dt><dd>${trackerText(k.day30)}</dd><dt>60-Day Target</dt><dd>${trackerText(k.day60)}</dd><dt>90-Day Target</dt><dd>${trackerText(k.day90)}</dd><dt>Actual</dt><dd>${trackerText(k.actual)}</dd><dt>Last Updated</dt><dd>${esc(k.updated)}</dd></dl><p>${esc(k.notes||'No notes entered')}</p><div class="spacer"></div><h3>Linked action plans</h3><div class="review-list">${plans.map(a=>`<button class="review-item readonly-report-link" data-action="action:${a.id}"><div><strong>${esc(a.title)}</strong><small>${esc(a.owner)} · ${esc(a.targetCompletion||'Timing not set')} · ${fmtDate(a.due)}</small></div>${trackerBadge(a.status)}</button>`).join('')||'<div class="subtle-note">No linked action plans yet.</div>'}</div><div class="spacer"></div><h3>Local change history</h3>${trackerHistoryHTML(k)}<div class="detail-note">KPI ownership, stable record links and local history are prototype enhancements. Status is manually entered by the BU. No automatic status is inferred from numeric or narrative target values.</div>`,button('Close','close')+(trackerCanEdit()?button('Add linked plan','tracker-new-plan:'+k.id,'','plus')+button('Edit KPI','tracker-edit-kpi:'+k.id,'primary','edit'):''),'KPI & Targets · Sample record')}
function trackerUnitModal(id){const u=trackerUnit(id);if(!u)return;const editable=trackerCanEdit();if(!editable){modal(u.name,`<dl class="definition-list"><dt>Portfolio</dt><dd>${u.group}</dd><dt>Company</dt><dd>${u.company}</dd>${u.group==='Pulse'?`<dt>Current Score</dt><dd>${u.score===null?'Not assessed':u.score}</dd><dt>Target Score</dt><dd>${u.scoreTarget===null?'Not set':u.scoreTarget}</dd>`:`<dt>Current Sales</dt><dd>${trackerPHP(u.sales)}</dd><dt>90-Day Target</dt><dd>${trackerPHP(u.target)}</dd><dt>Reserves</dt><dd>${trackerPHP(u.reserves)}</dd>`}</dl><p>${esc(u.notes)}</p><div class="spacer"></div><h3>Local history</h3>${trackerHistoryHTML(u)}`,button('Close','close'),'KPI & Targets · Sample inputs');return}modal(u.group==='Pulse'?'Update sample support score':'Update sample BU inputs',`<form id="tracker-form" data-form="tracker-unit" data-id="${id}">${trackerErrors()}<div class="detail-note">${u.name} · ${u.group} · ${u.company}</div>${u.group==='Pulse'?`<div class="field-grid">${trackerInput('score','Current Score (1–10)',u.score??'','number',false,'min="1" max="10" step="0.1"')}${trackerInput('scoreTarget','Target Score (1–10)',u.scoreTarget??'','number',false,'min="1" max="10" step="0.1"')}</div><p class="formhint">Leave a score blank if not assessed. Zero is not accepted as a true support score.</p>`:`<div class="field-grid">${trackerInput('sales','Current Sales (PHP)',u.sales,'number',true,'min="0" step="0.01"')}${trackerInput('target','90-Day Sales Target (PHP)',u.target,'number',true,'min="0" step="0.01"')}</div>${trackerInput('reserves','Separate reserves contribution (PHP)',u.reserves,'number',true,'min="0" step="0.01"')}`}<div class="spacer"></div>${trackerTextArea('notes','BU Notes',u.notes)}<p class="formhint">Derived company/BU totals and ratios will refresh from these local sample inputs.</p></form>`,button('Cancel','close')+'<button class="btn primary" type="submit" form="tracker-form">Save inputs</button>','KPI & Targets · '+trackerActor())}
function trackerGoalsModal(){if(!trackerCanReview()){toast('Use Corporate Planning preview to configure company sample goals.');return}const s=trackerData().settings;modal('Configure sample goals',`<form id="tracker-form" data-form="tracker-goals">${trackerErrors()}<div class="field-grid">${trackerInput('salesTarget','Company Gross Sales Target (PHP)',s.salesTarget,'number',true,'min="0.01" step="0.01"')}${trackerInput('reservesTarget','Company Reserves Target (PHP)',s.reservesTarget,'number',true,'min="0.01" step="0.01"')}</div><div class="field-grid">${trackerInput('start','90-day cycle start',s.start,'date',true)}${trackerInput('deadline','Company deadline',s.deadline,'date',true)}</div><p class="formhint">Cycle end is calculated as start + 89 days. The company deadline is separate. Goals must be positive. No official target or incentive is changed.</p></form>`,button('Cancel','close')+'<button class="btn primary" type="submit" form="tracker-form">Save sample goals</button>','KPI & Targets · Demo planning role')}
function trackerRemarksModal(id){const a=db.actions.find(a=>a.id===id);if(!a||!trackerFlagged(a.status)||!trackerCanReview()){toast('Corporate Planning remarks are available for At Risk or Delayed plans.');return}modal('Corporate Planning remarks',`<form id="tracker-form" data-form="tracker-remarks" data-id="${id}">${trackerErrors()}<div class="detail-note"><strong>${esc(a.title)}</strong><br>${esc(a.bu)} · ${esc(a.owner)} · ${esc(trackerStatus(a.status))}</div><h3>BU Notes</h3><p>${esc(a.notes||a.corrective||'No notes entered')}</p><div class="spacer"></div>${trackerTextArea('planningRemarks','CP Remarks (prototype enhancement)',a.planningRemarks||'',true)}<p class="formhint">The source uses status-cell highlighting and Notes. This separate CP Remarks field demonstrates the review workflow; it does not send a notification or edit a sheet comment.</p></form>`,button('Cancel','close')+'<button class="btn primary" type="submit" form="tracker-form">Save remarks</button>','Corporate Planning · Local demo only')}
function trackerValidate(type,f,id){if(type==='tracker-goals'){if(!trackerCanReview())return 'Switch to Corporate Planning preview to configure sample goals.';if(!f.salesTarget?.trim()||!f.reservesTarget?.trim()||![+f.salesTarget,+f.reservesTarget].every(n=>Number.isFinite(n)&&n>0))return 'Enter positive numeric company targets.';if(!trackerValidDate(f.start)||!trackerValidDate(f.deadline)||f.deadline<f.start)return 'Choose valid dates; the company deadline cannot precede cycle start.';return ''}if(type==='tracker-remarks'){const a=db.actions.find(a=>a.id===id);if(!trackerCanReview()||!a||!trackerFlagged(a.status))return 'Only the Corporate Planning preview can comment on flagged plans.';return !f.planningRemarks?.trim()?'Enter a review remark.':''}if(!trackerCanEdit())return 'Switch to the BU contributor preview to enter data.';if(type==='tracker-unit'){const u=trackerUnit(id);if(!u)return 'Business unit not found.';if(u.group==='Pulse'){for(const k of ['score','scoreTarget'])if(f[k]?.trim()&&(!Number.isFinite(+f[k])||+f[k]<1||+f[k]>10))return 'Assessed Pulse scores must be from 1 to 10; leave unknown scores blank.'}else if(['sales','target','reserves'].some(k=>!String(f[k]??'').trim()||!Number.isFinite(+f[k])||+f[k]<0))return 'Enter non-negative numeric sales, target and reserves values.';return ''}if(type==='tracker-kpi'){if(!trackerUnit(f.unitId))return 'Choose a valid business unit.';if(!f.name?.trim()||!f.owner?.trim())return 'KPI name and responsible person/team are required.';if(!['',...trackerStatuses,'N/A'].includes(f.status))return 'Choose a supported manual KPI status.';if(!trackerValidDate(f.updated))return 'Choose a valid Last Updated date.';return ''}return 'Unknown tracker form.'}
function trackerSaveForm(type,f,id){const error=trackerValidate(type,f,id);if(error){trackerShowError(error);return false}if(type==='tracker-kpi'){let k=trackerKpi(id);const before=k?structuredClone(k):null;if(!k){k={id:'tk-'+Date.now(),history:[]};trackerData().kpis.push(k)}const values=Object.fromEntries(['unitId','name','owner','baseline','day30','day60','day90','actual','status','updated','notes'].map(key=>[key,String(f[key]??'').trim()]));Object.assign(k,values);trackerHistory(k,before?'KPI updated':'KPI created',trackerChanges(before,values,{unitId:'Business unit',name:'KPI',owner:'Owner',baseline:'Baseline',day30:'30-Day Target',day60:'60-Day Target',day90:'90-Day Target',actual:'Actual',status:'Manual status',updated:'Last Updated',notes:'Notes'}));for(const a of db.actions.filter(a=>a.targetKpiId===k.id))a.bu=trackerUnit(k.unitId).name}else if(type==='tracker-unit'){const u=trackerUnit(id),before=structuredClone(u);if(u.group==='Pulse'){u.score=String(f.score??'').trim()===''?null:+f.score;u.scoreTarget=String(f.scoreTarget??'').trim()===''?null:+f.scoreTarget}else{u.sales=+f.sales;u.target=+f.target;u.reserves=+f.reserves}u.notes=String(f.notes||'').trim();trackerHistory(u,'BU inputs updated',trackerChanges(before,u,{sales:'Current Sales',target:'90-Day Target',reserves:'Reserves contribution',score:'Current Score',scoreTarget:'Target Score',notes:'BU Notes'}))}else if(type==='tracker-goals'){const s=trackerData().settings,before=structuredClone(s);Object.assign(s,{salesTarget:+f.salesTarget,reservesTarget:+f.reservesTarget,start:f.start,end:trackerDateAdd(f.start,89),deadline:f.deadline});trackerHistory(s,'Sample company goals updated',trackerChanges(before,s,{salesTarget:'Gross Sales Target',reservesTarget:'Reserves Target',start:'Cycle start',end:'Cycle end',deadline:'Company deadline'}))}else{const a=db.actions.find(a=>a.id===id),before=structuredClone(a);a.planningRemarks=f.planningRemarks.trim();trackerHistory(a,'Corporate Planning remarks added',trackerChanges(before,a,{planningRemarks:'CP Remarks'}))}save();closeModal();render();toast('Saved locally. No sheet or shared account was updated.');return true}
function trackerHandleAction(cmd,arg){if(cmd==='tracker-tab-from-actions'){state.trackerTab='register';navigate('targets');return}if(cmd==='tracker-planning-from-actions'){state.trackerTab='planning';navigate('targets');return}if(cmd==='tracker-tab'){state.trackerTab=arg;state.trackerStatus='All';render()}else if(cmd==='tracker-reset-filters'){state.trackerGroup='All';state.trackerUnit='All';state.trackerStatus='All';state.trackerSearch='';render()}else if(cmd==='tracker-add-kpi')trackerKpiModal(null,true);else if(cmd==='tracker-kpi')trackerKpiModal(arg);else if(cmd==='tracker-edit-kpi')trackerKpiModal(arg,true);else if(cmd==='tracker-unit')trackerUnitModal(arg);else if(cmd==='tracker-goals')trackerGoalsModal();else if(cmd==='tracker-remarks')trackerRemarksModal(arg);else if(cmd==='tracker-new-plan')actionModal(null,arg);else if(cmd==='tracker-edit-plan')actionModal(arg,null,true)}

document.addEventListener('click',e=>{const b=e.target.closest('button,[data-task],[data-finance-unit],[data-action]');if(!b)return;if(b.dataset.mode){state.mode=b.dataset.mode;state.portfolio='All';state.bu='All';navigate(state.mode==='ged'?'overview':'pace');return}if(b.dataset.nav){navigate(b.dataset.nav);return}if(b.dataset.portfolio){state.portfolio=b.dataset.portfolio;state.bu='All';state.page=state.portfolio==='Pulse'?'pulse':'overview';state.mode='ged';state.mobile=false;render();return}if(b.dataset.unit){state.bu=b.dataset.unit;render();return}if(b.dataset.metric){metricDetail(b.dataset.metric);return}if(b.dataset.trend){state.metric=b.dataset.trend;render();return}if(b.dataset.financeUnit){metricDetail('revenue',b.dataset.financeUnit);return}if(b.dataset.task){taskModal(b.dataset.task);return}if(b.dataset.project){projectModal(b.dataset.project);return}if(b.dataset.issue){issueModal(b.dataset.issue);return}const a=b.dataset.action;if(!a)return;const [cmd,...rest]=a.split(':'),arg=rest.join(':');if(cmd.startsWith('tracker-')){if(state.mode!=='ged')return;trackerHandleAction(cmd,arg);return}if(cmd==='close')closeModal();else if(cmd==='menu'){state.mobile=!state.mobile;render()}else if(cmd==='goto')navigate(arg);else if(cmd==='newaction')actionModal();else if(cmd==='task')taskModal(arg);else if(cmd==='pace')paceModal(arg);else if(cmd==='action')actionModal(arg);else if(cmd==='issue')issueModal(arg);else if(cmd==='project')projectModal(arg);else if(cmd==='exceptions')exceptionModal();else if(cmd==='exception')exceptionModal(arg);else if(cmd==='pulsemetric')pulseDetail('metric',arg);else if(cmd==='pulsedriver')pulseDetail('driver',arg);else if(cmd==='pulseunit')pulseDetail('unit',arg);else if(cmd==='definitions')metricDetail('revenue');else if(cmd==='export')exportCSV();else if(cmd==='downloadbrief'){const d=data();download('gencys-sample-executive-brief.txt',`GENCYS | ILLUSTRATIVE EXECUTIVE BRIEF\nNOT ACTUAL GENCYS DATA\n\nScope: ${scopeLabel()} | Period: ${state.period} 2026\nAs of: 30 Sep 2026 | Last updated: 09 Oct 2026\n\nGross Revenue: ${money(d.revenue)} / target ${money(d.revenueTarget)}\nOPEX: ${money(d.opex)} / target ${money(d.opexTarget)}\nWorking NPBT: ${money(d.npbt)}\nReserves: ${money(d.reserve)}\n\n${db.actions.length} sample action plans; ${db.projects.length} sample projects; ${db.issues.filter(i=>i.status==='Open').length} open demo issues.\n${hrisPaceReports.length} illustrative PACE reports. Creation and updates happen in HRIS; GOS is read-only.\n\nDefinitions and targets are for validation. Working NPBT = Gross Revenue - OPEX requires Finance / CEO validation.\nFinance API, HRIS retention, HRIS PACE and Gie's Google Sheet are planned sources, not connected.\n`)}else if(cmd==='resetpacefilters'){state.reportBu='All';state.reportPerson='All';state.reportStatus='All';state.reportFrom='2026-10-05';state.reportTo='2026-10-09';render()}else if(cmd==='reset'){if(state.mode==='gos'){toast('GOS is a read-only viewing layer.');return}modal('Reset this demo workspace?',`<p>This restores the browser-local sample actions, projects and operational examples. The read-only HRIS PACE sample reports remain unchanged. No source system is modified.</p>`,button('Keep my changes','close')+button('Reset sample data','confirmreset','danger'),'Browser-local data')}else if(cmd==='confirmreset'){if(state.mode==='gos')return;db=structuredClone(seed);save();closeModal();render();toast('Sample workspace restored.')}else if(cmd==='about'){modal('Explore the connected workspace',`<div class="review-list">${[['1','Inspect executive performance','Filter the period, portfolio and BU. Open KPI cards for actual, target, variance, dates and definition.'],['2','Set targets and act','Open KPIs & targets for sample BU inputs, 30/60/90-day KPIs and linked action plans. Switch demo roles to try weekly BU self-checks or Corporate Planning remarks on flagged plans.'],['3','View the operating rhythm','Switch to GOS. Filter HRIS-origin PACE examples, read the four fields and source history, and inspect weekly reporting status. Creation and updates happen in HRIS.'],['4','Understand data readiness','Data & integrations identifies planned sources, ownership and validation dependencies.']].map(r=>`<div class="review-item"><span class="avatar">${r[0]}</span><div><strong>${r[1]}</strong><small>${r[2]}</small></div></div>`).join('')}</div><div class="detail-note">All values are illustrative. GOS is a read-only report viewer. GED KPI, target, action and project edits stay in this browser. Demo roles are not real accounts or access controls. No live sync, real approvals, external messages or source edits occur.</div>`,button('Start exploring','close','primary'),'GED + GOS · Interactive prototype')}});
document.addEventListener('change',e=>{if(e.target.matches('[data-tracker-role]')){state.trackerRole=e.target.value;closeModal();render();return}if(e.target.dataset.trackerFilter){const k=e.target.dataset.trackerFilter;state[k]=e.target.value;if(k==='trackerGroup')state.trackerUnit='All';render();return}if(e.target.dataset.reportFilter){state[e.target.dataset.reportFilter]=e.target.value;render();return}if(e.target.matches('[data-weekly-report]')){state.weeklyId=e.target.value;render();return}if(e.target.dataset.filter){const k=e.target.dataset.filter;state[k]=e.target.value;if(k==='portfolio'){state.bu='All';state.page=state.portfolio==='Pulse'?'pulse':state.page==='pulse'?'overview':state.page}render()}if(e.target.dataset.milestone){const [id,i]=e.target.dataset.milestone.split(':');const p=db.projects.find(p=>p.id===id);p.checked=p.checked||p.milestones.map((_,idx)=>idx).filter(idx=>idx<Math.floor(p.progress/34));p.checked=e.target.checked?[...new Set([...p.checked,+i])]:p.checked.filter(idx=>idx!==+i);p.progress=Math.round(p.checked.length/p.milestones.length*100);p.status=p.progress===100?'Complete':p.status==='Complete'?'On track':p.status;log('Updated sample milestone: '+p.title);render();projectModal(p.id);toast('Milestone saved locally · '+p.progress+'% complete')}});
document.addEventListener('input',e=>{if(e.target.matches('[data-tracker-search]')){const pos=e.target.selectionStart;state.trackerSearch=e.target.value;render();const el=$('[data-tracker-search]');el?.focus();el?.setSelectionRange?.(pos,pos);return}if(e.target.matches('[data-search]')){const pos=e.target.selectionStart;state.query=e.target.value;render();const el=$('[data-search]');el?.focus();el?.setSelectionRange?.(pos,pos)}});
document.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const type=form.dataset.form;if(type!=='action'&&!type.startsWith('tracker-'))return;const f=Object.fromEntries(new FormData(form)),id=form.dataset.id;if(type.startsWith('tracker-')){trackerSaveForm(type,f,id);return}saveActionForm(f,id)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#modal-root').innerHTML)closeModal();else if(state.mobile){state.mobile=false;render()}}if(e.key==='Enter'&&e.target.matches('[role="button"]'))e.target.click();if(e.key==='Tab'&&$('#modal-root').innerHTML){const f=$$('#modal-root button,#modal-root a,#modal-root input,#modal-root select,#modal-root textarea').filter(e=>!e.disabled),first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
render();
